import java.util.Comparator;
import java.util.NavigableSet;
import java.util.TreeSet;

public class HighScoreLeaderboard {
    public record PlayerScore(String playerId, int score) {}

    private final NavigableSet<PlayerScore> leaderboard;

    public HighScoreLeaderboard() {
        // Solution: Sort descending by score; break ties using playerId to avoid dropping players
        Comparator<PlayerScore> comparator = Comparator
            .comparingInt(PlayerScore::score)
            .reversed()
            .thenComparing(PlayerScore::playerId);

        this.leaderboard = new TreeSet<>(comparator);
    }

    public boolean submitScore(String playerId, int score) {
        if (playerId == null) return false;
        return leaderboard.add(new PlayerScore(playerId, score));
    }

    public static void main(String[] args) {
        HighScoreLeaderboard board = new HighScoreLeaderboard();
        board.submitScore("Ninja", 1000);
        board.submitScore("Shadow", 1000); // Identical score!
        board.submitScore("Pixel", 850);

        System.out.println("Leaderboard size: " + board.leaderboard.size()); // Exactly 3!
        System.out.println("Top player: " + board.leaderboard.first());
    }
}

