import java.util.TreeSet;
import java.util.Comparator;

public class TaskSorter {
    public static class Task {
        public int priority;
        public String desc;
        public Task(int priority, String desc) { this.priority = priority; this.desc = desc; }
    }

    public static TreeSet<Task> createSortedSet(Task[] tasks) {
        Comparator<Task> comp = Comparator
            .comparingInt((Task t) -> t.priority)
            .thenComparing(t -> t.desc);
        TreeSet<Task> set = new TreeSet<>(comp);
        if (tasks != null) {
            for (Task t : tasks) if (t != null) set.add(t);
        }
        return set;
    }
}

