import java.util.List;
import java.util.TreeSet;

public class NullSanitizer {
    public static TreeSet<String> sanitizeAndSort(List<String> tokens) {
        TreeSet<String> set = new TreeSet<>();
        if (tokens != null) {
            for (String t : tokens) {
                if (t != null) set.add(t);
            }
        }
        return set;
    }
}

