import java.util.Set;
import java.util.HashSet;

public class DefensiveSetOps {
    public static Set<String> safeIntersection(Set<String> original, Set<String> filter) {
        if (original == null || filter == null) return new HashSet<>();
        Set<String> copy = new HashSet<>(original);
        copy.retainAll(filter);
        return copy;
    }
}

